return [{
  json: {
    callback_query: {
      data: 'approve:job_teste_123',
      id: 'cb_query_mock_999',
      from: { username: 'marciosouza' },
      message: { chat: { id: '123456789' } }
    }
  }
}];

// CORREÇÃO (auditoria v2.1): valida que a chamada realmente veio do
// Telegram usando o secret_token configurado via setWebhook (ver
// scripts/bash/setup-telegram-webhook.sh). O Telegram reenvia esse valor
// no header X-Telegram-Bot-Api-Secret-Token em toda chamada de callback.
const vindoDeWebhook = $json.headers !== undefined;
const secretEsperado = $env.TELEGRAM_WEBHOOK_SECRET_TOKEN;
if (vindoDeWebhook && secretEsperado) {
  const secretRecebido = $json.headers['x-telegram-bot-api-secret-token'];
  if (secretRecebido !== secretEsperado) {
    throw new Error('Callback não autorizado: secret_token do Telegram ausente ou incorreto.');
  }
}

const body = $json.body || $json || {};

const rawData = (body.callback_query?.data || body.message?.text || '').toString();
const [acao, jobId] = rawData.includes(':') ? rawData.split(':') : ['', ''];

const chatId = body.callback_query?.message?.chat?.id
  || body.message?.chat?.id
  || '';
const callbackQueryId = body.callback_query?.id || '';
const usuario = body.callback_query?.from?.username
  || body.message?.from?.username
  || 'desconhecido';

return [{
  json: {
    acao: acao.trim(),
    job_id: jobId.trim(),
    raw_data: rawData,
    chat_id: chatId,
    callback_query_id: callbackQueryId,
    aprovado_por: usuario,
    aprovado_em: new Date().toISOString()
  }
}];
